import { test, expect } from '@playwright/test';
import { writeFileSync } from 'node:fs';
import { login, seedStorage } from '../../tests/e2e/utils';

test('Local distinct actual Preview resource and navigation boundary probe', async ({page, context, browser}) => {
  const origin='http://localhost:3001';
  const endpoint='/api/cvf-local-preview-review';
  const off='https://review-preview.invalid';
  let phase='control';
  const hits: {phase:string;kind:string;url:string}[]=[];
  const unexpected: string[]=[];
  await context.route('**/*', async route=>{
    const u=new URL(route.request().url());
    if(u.pathname===endpoint){
      const kind=u.searchParams.get('kind')||'unknown';
      hits.push({phase,kind,url:u.origin+u.pathname+'?kind='+kind});
      if(kind==='css') return route.fulfill({contentType:'text/css',body:'.local-external{color:rgb(20,30,40)}'});
      if(kind==='navigate') return route.fulfill({contentType:'text/html',body:`<!doctype html><h1>Local navigation destination</h1><img src="${off}${endpoint}?kind=after-navigation">`});
      return route.fulfill({contentType:'image/svg+xml',body:'<svg xmlns="http://www.w3.org/2000/svg" width="1" height="1"><rect width="1" height="1"/></svg>'});
    }
    let sub=false;try{sub=route.request().frame().parentFrame()!==null;}catch{}
    if(sub&&!['about:','data:','blob:'].includes(u.protocol)){
      unexpected.push(u.origin+u.pathname);
      return route.abort();
    }
    return route.continue();
  });
  const common=`<!doctype html><html><head><style>h1{color:rgb(17,34,51)}.local-inline{padding-left:7px}</style></head><body><h1>LOCAL_PREVIEW_DISTINCT_Q7</h1><p class="local-inline">LOCAL_BENIGN_INLINE</p><img src="${origin}${endpoint}?kind=image"><link rel="stylesheet" href="${off}${endpoint}?kind=css"><div style="background-image:url('${off}${endpoint}?kind=background')">Resource box</div><a id="local-nav" href="${off}${endpoint}?kind=navigate">Local controlled navigation</a><script>document.documentElement.dataset.localRan='yes'</script></body></html>`;
  await page.setContent('<iframe id="local-control" sandbox=""></iframe>');
  await page.locator('#local-control').evaluate((e,html)=>(e as HTMLIFrameElement).srcdoc=html,common);
  await expect.poll(()=>hits.filter(h=>h.phase==='control').length).toBe(3);
  const positive=hits.filter(h=>h.phase==='control');
  await page.locator('#local-control').evaluate(e=>e.remove());
  const canonical=common.replace('<head>',`<head><meta http-equiv="refresh" content="0;url=${off}${endpoint}?kind=automatic-refresh">`);
  let exportHits=0;
  await page.route('**/api/artifacts/export', async route=>{
    exportHits++;
    await route.fulfill({contentType:'application/json',body:JSON.stringify({success:true,data:{html:canonical,filename:'local-preview-q7.html',generatedAt:'2026-10-01T00:00:00Z',governanceState:'DRAFT_UNACCEPTED',verification:[]}})});
  });
  await seedStorage(page);await login(page);
  await page.evaluate(()=>localStorage.setItem('cvf_language','en'));
  await page.goto('/artifacts');
  phase='actual-preview';
  await page.getByLabel('Title').fill('Local probe Q7');
  await page.getByRole('button',{name:/Build HTML/i}).click();
  const iframe=page.locator('iframe[title="Preview"]');
  const frame=page.frameLocator('iframe[title="Preview"]');
  await expect(frame.getByRole('heading',{name:'LOCAL_PREVIEW_DISTINCT_Q7'})).toBeVisible();
  await page.waitForTimeout(1200);
  const negative={hits:hits.filter(h=>h.phase==='actual-preview'),sandbox:await iframe.getAttribute('sandbox'),derived:await iframe.getAttribute('srcdoc')!==canonical,origin:await frame.locator('html').evaluate(()=>location.origin),compatMode:await frame.locator('html').evaluate(()=>document.compatMode),scriptMarker:await frame.locator('html').getAttribute('data-local-ran'),headingColor:await frame.locator('h1').evaluate(e=>getComputedStyle(e).color),inlinePadding:await frame.locator('p').evaluate(e=>getComputedStyle(e).paddingLeft)};
  expect(negative.hits).toEqual([]);expect(negative.sandbox).toBe('');expect(negative.origin).toBe('null');expect(negative.derived).toBe(true);expect(negative.scriptMarker).toBeNull();expect(negative.headingColor).toBe('rgb(17, 34, 51)');expect(negative.inlinePadding).toBe('7px');
  phase='explicit-link-click';
  await frame.locator('#local-nav').click();
  await page.waitForTimeout(1000);
  const navigation={hits:hits.filter(h=>h.phase==='explicit-link-click'),frameUrls:page.frames().map(f=>f.url()),parentUrl:page.url()};
  writeFileSync('.next/cvf-preview-local-review/observations.json',JSON.stringify({browser:browser.version(),fixture:canonical,positive,negative,navigation,unexpected,exportHits},null,2));
  console.log('LOCAL_PROBE '+JSON.stringify({positive:positive.length,negative,navigation,unexpected,exportHits}));
  expect(unexpected).toEqual([]);expect(exportHits).toBe(1);
});
